import {
  badRequest,
  forceMembershipSchema,
  type BotRecord,
  type Logger,
  type PlatformName,
  type Storage,
} from '@botforge/core';
import type { BotManager } from './manager';

export interface InstallSpec {
  templateId: string;
  name: string;
  slug: string;
  platform: PlatformName;
  token: string;
  /** Identity generated by the installer package, kept stable across redeploys. */
  botId?: string;
  webhookSecret?: string;
  config?: Record<string, unknown>;
  forceMembership?: unknown;
}

export interface InstallResult {
  bot: BotRecord;
  created: boolean;
  webhookUrl: string;
  webhookRegistered: boolean;
}

export interface InstallOptions {
  storage: Storage;
  manager: BotManager;
  logger: Logger;
  spec: InstallSpec;
}

function normalizeSlug(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40);
}

function parseForceMembership(input: unknown) {
  if (input === undefined || input === null || input === '') return null;
  const parsed = forceMembershipSchema.safeParse(input);
  if (!parsed.success) {
    throw badRequest('تنظیمات عضویت اجباری نامعتبر است', parsed.error.flatten());
  }
  return parsed.data;
}

/**
 * Bootstraps the single bot described by deployment environment variables.
 *
 * The installer ships a config, never a database dump: on the first boot the
 * runtime creates the bot record (verifying the platform token), applies the
 * requested configuration and force-membership channels, and registers the
 * webhook at its own public URL. Re-running is idempotent, so a redeploy with
 * changed settings updates the existing record instead of duplicating it.
 */
export async function ensureInstalledBot(options: InstallOptions): Promise<InstallResult> {
  const { storage, manager, logger, spec } = options;
  const slug = normalizeSlug(spec.slug);
  if (slug.length < 3) throw badRequest('شناسه نصب باید حداقل ۳ کاراکتر لاتین باشد');
  if (!spec.token || spec.token.length < 20) throw badRequest('توکن ربات برای نصب خودکار نامعتبر است');

  const template = manager.templateFor(spec.templateId);
  if (!template) throw badRequest(`قالب ${spec.templateId} در این نسخه موجود نیست`);

  const forceMembership = parseForceMembership(spec.forceMembership);
  const config = { ...(spec.config ?? {}) };

  let bot = await storage.bots.findBySlug(slug);
  let created = false;

  if (!bot) {
    bot = await manager.createBot({
      templateId: spec.templateId,
      name: spec.name || template.name,
      slug,
      platform: spec.platform,
      token: spec.token.trim(),
      config,
      ownerId: 'installer',
      id: spec.botId,
      webhookSecret: spec.webhookSecret,
    });
    created = true;
    logger.info('installer created bot', { botId: bot.id, templateId: spec.templateId });
  } else {
    if (bot.templateId !== spec.templateId) {
      throw badRequest(
        `نصب موجود با قالب ${bot.templateId} ثبت شده است؛ برای تغییر قالب یک نصب تازه با شناسه دیگر بسازید`,
      );
    }
    if (bot.platform !== spec.platform) {
      throw badRequest(`نصب موجود روی پلتفرم ${bot.platform} است؛ پلتفرم را در تنظیمات نصب تغییر دهید`);
    }
    const patch: Partial<BotRecord> = { updatedAt: new Date().toISOString() };
    if (spec.name) patch.name = spec.name;
    if (Object.keys(config).length > 0) patch.config = { ...bot.config, ...config };
    bot = (await storage.bots.update(bot.id, patch)) ?? bot;
    logger.info('installer reused bot', { botId: bot.id });
  }

  if (forceMembership) {
    const updated = await storage.bots.update(bot.id, {
      forceMembership,
      updatedAt: new Date().toISOString(),
    });
    if (updated) bot = updated;
    await storage.events.log({
      botId: bot.id,
      type: 'installer.force_membership_applied',
      level: 'info',
      payload: { enabled: forceMembership.enabled, channels: forceMembership.channels.length },
    });
  }

  await manager.reload(bot.id);
  const webhookRegistered = await manager.registerWebhook(bot);
  const webhookUrl = manager.webhookUrl(bot);

  await storage.events.log({
    botId: bot.id,
    type: created ? 'installer.installed' : 'installer.reconciled',
    level: webhookRegistered ? 'info' : 'warn',
    payload: { webhookRegistered, platform: bot.platform, template: bot.templateId },
  });

  return { bot, created, webhookUrl, webhookRegistered };
}
